            aOrbiterF = (((aWandererA + RotL64(aCross, 39U)) + RotL64(aCarry, 5U)) + 0xDF34A8891A95DF1AULL) + aOrbiterAssignSaltD[(((31U - aIndex) + 9U)) & S_SALT1];
