            aOrbiterD = (aOrbiterD + aOrbiterH) + 0x9E43AADBD4D1FC4AULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterD) ^ 0x134F504D497AEAECULL) ^ aOrbiterUpdateSaltB[((aIndex + 13U)) & S_SALT1];
