            //
            aOrbiterC = (aOrbiterC + aOrbiterF) + 0x5C7CE9C5EB1963CBULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterC) ^ 0x528AB865C5AF416FULL;
