            aIngress = (RotL64(aHeartLaneA[((aIndex + 16023U)) & S_BLOCK1], 38U) ^ RotL64(aPoisonLaneC[((aIndex + 13314U)) & S_BLOCK1], 47U));
            aIngress ^= (RotL64(aWaterLaneB[((aIndex + 12816U)) & S_BLOCK1], 29U) ^ RotL64(aWaterLaneC[((aIndex + 16350U)) & S_BLOCK1], 57U));
