            aOrbiterD = (aOrbiterD + aOrbiterG) + 0x5306E90DD233DC40ULL;
            aOrbiterB = (((aOrbiterB ^ aOrbiterD) ^ 0xF3F1C7A4A4058C16ULL) ^ aOrbiterUpdateSaltF[((aIndex + 21U)) & S_SALT1]) ^ aNonceWordF;
            aOrbiterB = RotL64((aOrbiterB * 0x43F6370B6797850BULL), 19U);
