            aOrbiterK = (aOrbiterK + aOrbiterB) + 0x15D62481282B1D3CULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterK) ^ 0xA97CBA5E5678F3B8ULL) ^ aOrbiterUpdateSaltE[(((31U - aIndex) + 27U)) & S_SALT1];
