            aOrbiterB = (aOrbiterB ^ aOrbiterF) ^ 0x923A191DD2AC163EULL;
            aOrbiterB = RotL64((aOrbiterB * 0x629891BB8F1E3F0BULL), 57U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterB) + 0xE64FAAE7ADA6B103ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterJ) ^ 0xFCB1E2B6CEA11150ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xF7E6EF33BF673971ULL), 27U);
            //
