            aIngress = aIngress + (RotL64(aOrbiterA, 39U) ^ aOrbiterF);
            aIngress = aIngress + RotL64(aOrbiterB, 57U);
            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererB = aWandererB ^ ((RotL64(aIngress, 4U) + RotL64(aOrbiterC, 53U)) + aOrbiterA);
            aWandererI = aWandererI + ((((RotL64(aCross, 19U) + aOrbiterB) + RotL64(aOrbiterJ, 39U)) + RotL64(aCarry, 5U)) + aPhaseCWandererUpdateSaltA[((aIndex + 11U)) & S_SALT1]);
            aWandererA = aWandererA ^ ((RotL64(aPrevious, 27U) + RotL64(aOrbiterH, 60U)) + aOrbiterC);
            aWandererE = aWandererE + ((RotL64(aScatter, 51U) + aOrbiterF) + RotL64(aOrbiterA, 11U));
            aWandererF = aWandererF ^ ((RotL64(aCross, 35U) + aOrbiterJ) + RotL64(aOrbiterC, 29U));
            aWandererG = aWandererG + ((((RotL64(aPrevious, 13U) + RotL64(aOrbiterF, 47U)) + aOrbiterH) + RotL64(aCarry, 57U)) + aPhaseCWandererUpdateSaltE[(((31U - aIndex) + 10U)) & S_SALT1]);
            aWandererK = aWandererK ^ ((RotL64(aIngress, 57U) + aOrbiterJ) + RotL64(aOrbiterE, 21U));
