            //
            aOrbiterG = (aWandererE + RotL64(aPrevious, 11U)) + 0x3DAEB2B66B2E56AFULL;
            aOrbiterJ = (((aWandererF + RotL64(aCross, 21U)) + RotL64(aCarry, 13U)) + 0x8B5062DD4B188D5DULL) + aPhaseBOrbiterAssignSaltF[((aIndex + 8U)) & S_SALT1];
            aOrbiterD = (aWandererJ + RotL64(aScatter, 35U)) + 0x83CFCE2431DBC9AFULL;
            aOrbiterF = ((aWandererA + RotL64(aIngress, 27U)) + RotL64(aCarry, 51U)) + 0xF5C54B1B6309C944ULL;
            aOrbiterA = ((aWandererG + RotL64(aPrevious, 53U)) + 0x5DA198CB556DC531ULL) + aPhaseBOrbiterAssignSaltB[((aIndex + 25U)) & S_SALT1];
