            //
            aIngress = (RotL64(aWoodLaneA[((aIndex + 7734U)) & S_BLOCK1], 3U) ^ RotL64(aFireLaneC[((aIndex + 7961U)) & S_BLOCK1], 56U));
            aIngress ^= RotL64(aPoisonLaneD[((S_BLOCK1 - aIndex + 6762U)) & S_BLOCK1], 21U);
            aIngress = TwistMix64::DiffuseC(aIngress);
            //
            aCross = (RotL64(aFireLaneA[((S_BLOCK1 - aIndex + 9686U)) & S_BLOCK1], 35U) ^ RotL64(aFireLaneD[((S_BLOCK1 - aIndex + 7883U)) & S_BLOCK1], 23U));
            aCross ^= RotL64(aEarthLaneB[((S_BLOCK1 - aIndex + 6205U)) & S_BLOCK1], 10U);
            aCross = TwistMix64::DiffuseA(aCross);
            //
            aScatter = (RotL64(aPrevious, 51U) ^ RotL64(aCross, 5U)) ^ (RotL64(aIngress, 21U) + RotL64(aCarry, 34U));
            aScatter = TwistMix64::DiffuseC(aScatter);
            //
            aOrbiterH = (aWandererD + RotL64(aPrevious, 3U)) + 0x423592EC63E0366FULL;
            aOrbiterE = ((aWandererJ + RotL64(aIngress, 11U)) + RotL64(aCarry, 53U)) + 0x687DCF1AECF90AEEULL;
            aOrbiterG = (aWandererB + RotL64(aScatter, 44U)) + 0x6B9858839C554A4CULL;
            aOrbiterJ = (aWandererK + RotL64(aCross, 35U)) + 0xF0B7E7368D1A2A31ULL;
            aOrbiterA = (((aWandererF + RotL64(aPrevious, 51U)) + RotL64(aCarry, 27U)) + 0x3D5A35F73E21FB0FULL) + aPhaseDOrbiterAssignSaltC[(((31U - aIndex) + 14U)) & S_SALT1];
            aOrbiterK = ((aWandererC + RotL64(aCross, 23U)) + RotL64(aCarry, 3U)) + 0x9911FB97B64B0C4AULL;
            aOrbiterB = ((aWandererH + RotL64(aScatter, 57U)) + 0xA365A5A7C2A57814ULL) + aPhaseDOrbiterAssignSaltF[((aIndex + 13U)) & S_SALT1];
            //
            aOrbiterH = ((aOrbiterH + aOrbiterE) + 0xA5988316423B7098ULL) + aPhaseDOrbiterUpdateSaltD[(((31U - aIndex) + 29U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterH) ^ 0x316A0D0E9FACCB1CULL;
            aOrbiterG = RotL64((aOrbiterG * 0x9E7999E4183D487BULL), 57U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterJ) + 0xB64541A1388223CDULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterG) ^ 0x92DFAD2CE7D21687ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xD93A222A568C1499ULL), 29U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterK) + 0xF30EE033348B3759ULL) + aPhaseDOrbiterUpdateSaltE[((aIndex + 5U)) & S_SALT1];
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterE) ^ 0xBC909B4D6635760FULL) ^ aPhaseDOrbiterUpdateSaltB[((aIndex + 21U)) & S_SALT1];
