            //
            aOrbiterK = (aOrbiterK + aOrbiterG) + 0x95D5BCA1D9A63017ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterK) ^ 0x4F9CB9AAF85B3E57ULL;
            aOrbiterB = RotL64((aOrbiterB * 0xC1A4F16A93141F49ULL), 3U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterB) + 0xAD6BDE0B25C1E39BULL) + aPhaseDOrbiterUpdateSaltA[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterJ) ^ 0xB3D16EF8BAF765EFULL;
            aOrbiterH = RotL64((aOrbiterH * 0x430B7BE71597861DULL), 37U);
            //
