            //
            aOrbiterI = (aWandererE + RotL64(aCross, 41U)) + 0xB5A534B5C4606EDCULL;
            aOrbiterC = ((aWandererA + RotL64(aScatter, 35U)) + 0xFA8337EF49A6098BULL) + aPhaseBOrbiterAssignSaltE[(((31U - aIndex) + 29U)) & S_SALT1];
            aOrbiterD = ((aWandererH + RotL64(aPrevious, 3U)) + RotL64(aCarry, 23U)) + 0xB5728CCF24AC5BDCULL;
            aOrbiterG = (aWandererB + RotL64(aIngress, 58U)) + 0x67BB6DB8535C8142ULL;
            aOrbiterA = ((aWandererJ + RotL64(aCross, 51U)) + RotL64(aCarry, 5U)) + 0x78579D71D4F0AE94ULL;
            aOrbiterB = (((aWandererD + RotL64(aIngress, 21U)) + RotL64(aCarry, 39U)) + 0xD46A7991ED2DDB71ULL) + aPhaseBOrbiterAssignSaltF[((aIndex + 5U)) & S_SALT1];
            aOrbiterF = (aWandererG + RotL64(aScatter, 11U)) + 0x5FC643DC08EDBFB4ULL;
            //
            aOrbiterI = (aOrbiterI + aOrbiterC) + 0xC8247B8B7F398352ULL;
