            aOrbiterD = RotL64((aOrbiterD * 0x4136240F31B08B11ULL), 41U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterI) + 0x67B0BB14A27A72B7ULL) + aPhaseBOrbiterUpdateSaltC[(((31U - aIndex) + 27U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterG) ^ 0x2851EB86CDD4619AULL;
            aOrbiterA = RotL64((aOrbiterA * 0x292FEEADD3444C89ULL), 57U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterB) + 0x5D6F737F3A565016ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterC) ^ 0x163DA6E13B9E5304ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x6A8AB195C8B4AF37ULL), 47U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterA) + 0x489FA283B62FE172ULL) + aPhaseBOrbiterUpdateSaltF[((aIndex + 26U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterF) ^ 0x7E96927F5E83CB73ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x162497AAC3C91E07ULL), 3U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterG) + 0x52F795ADC0C167D2ULL) + aPhaseBOrbiterUpdateSaltA[(((31U - aIndex) + 25U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterD) ^ 0xA6469390ACF55693ULL;
