            aWandererH = aWandererH + ((((RotL64(aScatter, 41U) + aOrbiterA) + RotL64(aOrbiterD, 29U)) + RotL64(aCarry, 23U)) + aPhaseBWandererUpdateSaltE[(((31U - aIndex) + 3U)) & S_SALT1]);
